import Image from "next/image";
import Link from "next/link";
import { ViewTransition } from "react";
import type { ProductCard as Card } from "@/lib/catalog";
import { discountPercent } from "@/lib/money";
import { EmiHint, Price } from "./Price";
import { Stars } from "./Stars";
import { WishlistButton } from "./WishlistButton";
import { QuickAdd } from "./QuickAdd";
import { Reveal } from "./Reveal";

/**
 * `morph` gives the image a shared view-transition name so it morphs into the product page.
 * Only enable it where each product appears once on the page (duplicate names cancel the transition).
 */
export function ProductCard({ product, morph = false }: { product: Card; morph?: boolean }) {
  const [img, alt] = product.images;
  const off = discountPercent(product.price, product.mrp);
  const image = (
    <div data-product-image className="relative aspect-square overflow-hidden bg-paper">
      {img && (
        <Image
          src={img.url}
          alt={img.alt ?? product.name}
          fill
          sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
          className="object-contain p-3 transition duration-500 ease-out group-hover:scale-[1.06]"
        />
      )}
      {alt && (
        <Image
          src={alt.url}
          alt=""
          aria-hidden
          fill
          sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
          className="object-contain p-3 opacity-0 transition duration-500 ease-out group-hover:scale-[1.06] group-hover:opacity-100"
        />
      )}
    </div>
  );

  return (
    <div data-product-card className="group relative flex h-full flex-col overflow-hidden rounded-xl border border-line bg-white transition duration-300 ease-out hover:-translate-y-1 hover:border-brass/40 hover:shadow-[0_12px_30px_-12px_rgb(0_0_0/0.25)]">
      <Link href={`/product/${product.slug}`} className="flex flex-1 flex-col focus-visible:outline-2 focus-visible:outline-brass">
        {morph ? (
          <ViewTransition name={`product-${product.id}`} share="morph" default="none">
            {image}
          </ViewTransition>
        ) : (
          image
        )}
        <div className="flex flex-1 flex-col gap-1.5 p-3">
          {product.material && <span className="text-[11px] font-semibold uppercase tracking-wide text-steel">{product.material}</span>}
          <h3 className="line-clamp-2 text-sm font-medium leading-snug text-ink transition-colors group-hover:text-maroon">{product.name}</h3>
          {product.ratingCount > 0 && <Stars value={product.ratingAvg} count={product.ratingCount} />}
          <div className="mt-auto pt-1">
            <Price price={product.price} mrp={product.mrp} size="sm" />
            <EmiHint price={product.price} emiEligible={product.emiEligible} />
          </div>
        </div>
      </Link>

      {/* Overlay matching the square image area: badges, wishlist, quick add. */}
      <div className="pointer-events-none absolute inset-x-0 top-0 aspect-square">
        <div className="absolute left-2 top-2 flex flex-col gap-1">
          {off >= 10 && <span className="badge bg-maroon text-white shadow-sm">{off}% OFF</span>}
          {product.engravingAvailable && <span className="badge bg-brass-light text-brass">Engraving</span>}
        </div>
        <div className="pointer-events-auto absolute right-2 top-2">
          <WishlistButton productId={product.id} name={product.name} />
        </div>
        {product.stock === 0 ? (
          <span className="absolute inset-x-0 bottom-0 bg-ink/80 py-1 text-center text-xs font-semibold text-white">Out of stock</span>
        ) : (
          <div className="pointer-events-auto absolute bottom-2 right-2 transition duration-300 ease-out sm:translate-y-2 sm:opacity-0 sm:group-focus-within:translate-y-0 sm:group-focus-within:opacity-100 sm:group-hover:translate-y-0 sm:group-hover:opacity-100">
            <QuickAdd productId={product.id} name={product.name} />
          </div>
        )}
      </div>
    </div>
  );
}

export function ProductGrid({ products }: { products: Card[] }) {
  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4 lg:grid-cols-4">
      {products.map((p, i) => (
        <Reveal key={p.id} delay={(i % 4) * 70}>
          <ProductCard product={p} morph />
        </Reveal>
      ))}
    </div>
  );
}

export function ProductRail({ title, href, products }: { title: string; href?: string; products: Card[] }) {
  if (!products.length) return null;
  return (
    <Reveal as="section" className="py-6">
      <div className="mb-4 flex items-end justify-between">
        <h2 className="font-display text-2xl font-semibold">{title}</h2>
        {href && <Link href={href} className="group/see text-sm font-semibold text-maroon">See all <span className="inline-block transition-transform group-hover/see:translate-x-1">→</span></Link>}
      </div>
      <div className="no-scrollbar -mx-4 flex snap-x gap-3 overflow-x-auto scroll-smooth px-4 pb-3 pt-1 sm:mx-0 sm:px-0">
        {products.map((p) => (
          <div key={p.id} className="w-[46%] shrink-0 snap-start sm:w-[31%] lg:w-[23.5%]">
            <ProductCard product={p} />
          </div>
        ))}
      </div>
    </Reveal>
  );
}
