import { discountPercent, emiMonthly, formatINR, INDICATIVE_EMI_RATE } from "@/lib/money";
import { EMI_MIN_AMOUNT } from "@/lib/site";
import { cn } from "@/lib/utils";

export function Price({ price, mrp, size = "md" }: { price: number; mrp: number; size?: "sm" | "md" | "lg" }) {
  const off = discountPercent(price, mrp);
  return (
    <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
      {off > 0 && size === "lg" && <span className="text-2xl font-light text-maroon">-{off}%</span>}
      <span className={cn("font-semibold text-ink", size === "lg" ? "text-3xl" : size === "md" ? "text-lg" : "text-base")}>{formatINR(price)}</span>
      {off > 0 && (
        <>
          <span className="text-sm text-muted">
            {size === "lg" && "M.R.P.: "}
            <s>{formatINR(mrp)}</s>
          </span>
          {size !== "lg" && <span className="text-sm font-medium text-success">{off}% off</span>}
        </>
      )}
    </div>
  );
}

export function EmiHint({ price, emiEligible }: { price: number; emiEligible: boolean }) {
  if (!emiEligible || price < EMI_MIN_AMOUNT) return null;
  return (
    <p className="text-xs text-ink-soft">
      EMI from <span className="font-semibold">{formatINR(emiMonthly(price, INDICATIVE_EMI_RATE, 12))}/mo</span>
    </p>
  );
}
